def render(data: dict, rel: str) -> str:
    ident = 'x148-' + rel.split('/')[0].replace('.', '-')
    cards = ''.join(f'<article class="x146-depth__card"><h3>{h}</h3><p>{p}</p></article>' for h, p in data['cards'])
    links = ''.join(f'<a href="{href}">{label}</a>' for href, label in data['links'])
    return (
        f'<section class="x146-depth" data-stage148-discovery="true" aria-labelledby="{ident}">'
        '<div class="x146-depth__inner"><div class="x146-depth__head">'
        f'<p class="x146-depth__eyebrow">{data["eyebrow"]}</p><div>'
        f'<h2 id="{ident}">{data["title"]}</h2><p class="x146-depth__intro">{data["intro"]}</p>'
        f'</div></div><div class="x146-depth__grid">{cards}</div>'
        f'<nav class="x146-depth__links" aria-label="Связанные страницы">{links}</nav>'
        '</div></section>'
    )

changed = 0
for rel, data in PAGES.items():
    path = ROOT / rel
    if not path.is_file():
        raise SystemExit(f'stage148: missing {rel}')
    html = path.read_text(encoding='utf-8')
    html = re.sub(r'\s*<section\b[^>]*data-stage148-discovery="true"[^>]*>.*?</section>\s*', '\n', html, count=1, flags=re.I | re.S)
    html = re.sub(r'<link\b[^>]*data-stage146-seo-depth-style="true"[^>]*>\s*', '', html, flags=re.I)
    if '</head>' not in html or '</main>' not in html:
        raise SystemExit(f'stage148: document markers missing in {rel}')
    html = html.replace('</head>', STYLE + '</head>', 1)
    html = html.replace('</main>', render(data, rel) + '\n</main>', 1)
    path.write_text(html, encoding='utf-8')
    changed += 1

TITLE_FIXES = {
    'guides/custom-crm-or-ready/index.html': 'Своя CRM или готовая: что выбрать в 2026 | Alexuys',
    'cases/factory-catalog/index.html': 'B2B-каталог завода с интеграцией 1С | Кейс Alexuys',
}
for rel, title in TITLE_FIXES.items():
    path = ROOT / rel
    if not path.is_file():
        raise SystemExit(f'stage148: title target missing {rel}')
    html = path.read_text(encoding='utf-8')
    html, count = re.subn(r'<title>.*?</title>', f'<title>{title}</title>', html, count=1, flags=re.I | re.S)
    if count != 1:
        raise SystemExit(f'stage148: title missing in {rel}')
    html = re.sub(r'(<meta\b[^>]*property=["\']og:title["\'][^>]*content=["\'])[^"\']*(["\'])', rf'\1{title}\2', html, count=1, flags=re.I)
    html = re.sub(r'(<meta\b[^>]*name=["\']twitter:title["\'][^>]*content=["\'])[^"\']*(["\'])', rf'\1{title}\2', html, count=1, flags=re.I)
    path.write_text(html, encoding='utf-8')

if changed != len(PAGES):
    raise SystemExit(f'stage148: expected {len(PAGES)} discovery pages, got {changed}')
print(f'stage148 discovery hubs: enriched={changed}; titles={len(TITLE_FIXES)}')
